import type { SqlExecutor } from '../../platform/persistence/postgres-boundary';
import { ensureIdempotency, requestHash, saveIdempotency } from '../../platform/persistence/transaction-store';
import { assertReturnTransition, nextStatusForInspection } from './state';
import { isReturnReason, isReturnStatus, isReturnCondition, isInspectionDecision, normalizeNote, normalizePositiveInteger, normalizePositiveMoney, type ReturnReasonCode, type ReturnItemCondition, type InspectionDecision, type ReturnStatus, type CreateReturnInput } from './contracts';
import type { ReturnRecord, ReturnItemRecord, SettlementCalculation, InspectionInput, ReturnCommandResult } from './contracts';
import { syncPostSaleCaseTx } from '../../platform/post-sale-orchestration';
import { recordPostSaleFinancialEventTx, postRefundAccountingTx, recoverReturnInventoryTx } from '../../platform/post-sale-finance';

type Tx=SqlExecutor;
type ReturnRow={id:string;order_id:string;customer_id:string|null;status:ReturnStatus;reason_code:ReturnReasonCode;reason_note:string|null;requested_at:string;updated_at:string};
type ItemRow={id:string;return_id:string;order_item_id:string;quantity:number;condition:ReturnItemCondition;inspection_note:string|null};
type OrderItemRow={id:string;product_id:string;quantity:number;unit_price:number|string;title:string|null};
function requireId(value:unknown,name:string){if(typeof value!=='string'||!value.trim())throw new Error(`INVALID_${name.toUpperCase()}`);return value.trim();}
function requireMoney(value:unknown,name:string){const n=normalizePositiveMoney(value);if(n===undefined)throw new Error(`INVALID_${name.toUpperCase()}`);return n;}
function mapReturn(row:ReturnRow):ReturnRecord{return{id:row.id,orderId:row.order_id,customerId:row.customer_id,status:row.status,reasonCode:row.reason_code,reasonNote:row.reason_note,requestedAt:row.requested_at,updatedAt:row.updated_at};}
function mapItem(row:ItemRow):ReturnItemRecord{return{id:row.id,returnId:row.return_id,orderItemId:row.order_item_id,quantity:Number(row.quantity),condition:row.condition,inspectionNote:row.inspection_note};}
async function lockReturn(tx:Tx,id:string){const r=await tx.query<ReturnRow>('select id,order_id,customer_id,status,reason_code,reason_note,requested_at,updated_at from trust_returns where id=$1 for update',[id]);if(!r.rows[0])throw new Error('RETURN_NOT_FOUND');return r.rows[0];}
async function ensureCustomerOwnsOrder(tx:Tx,orderId:string,customerId:string){const r=await tx.query<{customer_id:string|null}>('select customer_id from trust_orders where id=$1 for update',[orderId]);if(!r.rows[0])throw new Error('ORDER_NOT_FOUND');if(r.rows[0].customer_id!==customerId)throw new Error('ORDER_ACCESS_DENIED');}
async function ensureItemBelongs(tx:Tx,orderId:string,itemId:string){const r=await tx.query<OrderItemRow & {seller_order_id:string|null}>('select oi.id,oi.product_id,oi.quantity,oi.unit_price,p.title,oi.seller_order_id from trust_order_items oi join trust_products p on p.id=oi.product_id where oi.id=$1 and oi.order_id=$2',[itemId,orderId]);if(!r.rows[0])throw new Error('ORDER_ITEM_NOT_FOUND');return r.rows[0];}
async function appendReturnEvent(tx:Tx,input:{returnId:string;from:ReturnStatus|null;to:ReturnStatus;source:string;actorId?:string;note?:string}){await tx.query('insert into trust_return_events(return_id,from_status,to_status,source,actor_id,note) values($1,$2,$3,$4,$5,$6)',[input.returnId,input.from,input.to,input.source,input.actorId??null,input.note??null]);await tx.query('insert into trust_outbox_events(event_type,aggregate_id,payload_json) values($1,$2,$3::jsonb)',['return.status_changed',input.returnId,JSON.stringify({from:input.from,to:input.to,source:input.source,actorId:input.actorId??null,note:input.note??null})]);}
async function transitionReturnTx(tx:Tx,input:{returnId:string;to:ReturnStatus;source:string;actorId?:string;note?:string}){const row=await lockReturn(tx,input.returnId);assertReturnTransition(row.status,input.to);if(row.status===input.to)return{...mapReturn(row),changed:false};await tx.query('update trust_returns set status=$2,updated_at=now(),approved_at=case when $2=\'APPROVED\' then now() else approved_at end,received_at=case when $2=\'RECEIVED\' then now() else received_at end,inspected_at=case when $2=\'APPROVED_REFUND\' or $2=\'REJECTED\' then now() else inspected_at end,closed_at=case when $2=\'CLOSED\' then now() else closed_at end where id=$1',[input.returnId,input.to]);await appendReturnEvent(tx,{returnId:input.returnId,from:row.status,to:input.to,source:input.source,actorId:input.actorId,note:input.note});await syncPostSaleCaseTx(tx,{returnId:input.returnId,returnStatus:input.to,orderId:row.order_id,customerId:row.customer_id,event:transitionReason(row.status,input.to)});return{...mapReturn(row),status:input.to,changed:true};}
export async function createReturn(db:Tx,input:CreateReturnInput):Promise<ReturnCommandResult>{
 const orderId=requireId(input.orderId,'order_id');const customerId=requireId(input.customerId,'customer_id');const key=requireId(input.idempotencyKey,'idempotency_key');if(!isReturnReason(input.reasonCode))throw new Error('INVALID_RETURN_REASON');if(!Array.isArray(input.items)||input.items.length===0)throw new Error('RETURN_ITEMS_REQUIRED');
 const unique=new Set<string>();for(const item of input.items){const id=requireId(item.orderItemId,'order_item_id');const q=normalizePositiveInteger(item.quantity);if(q===undefined)throw new Error('INVALID_RETURN_QUANTITY');if(unique.has(id))throw new Error('DUPLICATE_RETURN_ITEM');unique.add(id);}
 return db.transaction(async tx=>{const hash=requestHash('return.create',{orderId,customerId,reasonCode:input.reasonCode,reasonNote:normalizeNote(input.reasonNote),items:input.items.map(x=>({orderItemId:x.orderItemId,quantity:x.quantity}))});const cached=await ensureIdempotency(tx,key,'return.create',hash);if(cached)return{...(cached as ReturnCommandResult),replay:true};await ensureCustomerOwnsOrder(tx,orderId,customerId);const order=await tx.query<{status:string}>('select status from trust_orders where id=$1',[orderId]);if(!['delivered','shipped'].includes(order.rows[0].status))throw new Error('ORDER_NOT_RETURNABLE');
 const inserted=await tx.query<{id:string}>(`insert into trust_returns(order_id,customer_id,status,reason_code,reason_note) values($1,$2,'REQUESTED',$3,$4) returning id`,[orderId,customerId,input.reasonCode,normalizeNote(input.reasonNote)]);const returnId=inserted.rows[0].id;let count=0;
 for(const item of input.items){const oi=await ensureItemBelongs(tx,orderId,requireId(item.orderItemId,'order_item_id'));const existing=await tx.query<{qty:number}>('select coalesce(sum(quantity),0) qty from trust_return_items ri join trust_returns r on r.id=ri.return_id where ri.order_item_id=$1 and r.status not in (\'REJECTED\',\'CLOSED\')',[oi.id]);if(Number(existing.rows[0].qty)+item.quantity>Number(oi.quantity))throw new Error('RETURN_QUANTITY_EXCEEDS_ORDER');if(!oi.seller_order_id)throw new Error('SELLER_ORDER_NOT_FOUND_FOR_RETURN_ITEM');await tx.query('insert into trust_return_items(return_id,order_item_id,seller_order_id,quantity) values($1,$2,$3,$4)',[returnId,oi.id,oi.seller_order_id,item.quantity]);count+=1;}
 await appendReturnEvent(tx,{returnId,from:null,to:'REQUESTED',source:'customer',actorId:customerId,note:normalizeNote(input.reasonNote)});await syncPostSaleCaseTx(tx,{returnId,returnStatus:'REQUESTED',orderId,customerId,event:'RETURN_REQUESTED'});const result={returnId,status:'REQUESTED' as ReturnStatus,replay:false,itemCount:count};await saveIdempotency(tx,key,'return.create',result,86400,hash);return result;});}
export async function getReturn(db:Tx,input:{returnId:string;actorId:string;privileged?:boolean}){return db.query<ReturnRow>('select id,order_id,customer_id,status,reason_code,reason_note,requested_at,updated_at from trust_returns where id=$1 and ($2::boolean=true or customer_id=$3) ',[input.returnId,Boolean(input.privileged),input.actorId]).then(r=>r.rows[0]?mapReturn(r.rows[0]):undefined);}
export async function listCustomerReturns(db:Tx,customerId:string,limit=50){const id=requireId(customerId,'customer_id');const n=Math.min(Math.max(Number(limit)||50,1),100);const r=await db.query<ReturnRow>('select id,order_id,customer_id,status,reason_code,reason_note,requested_at,updated_at from trust_returns where customer_id=$1 order by created_at desc limit $2',[id,n]);return r.rows.map(mapReturn);}
export async function listOperationsReturns(db:Tx,filters:{status?:ReturnStatus;limit?:number}){const n=Math.min(Math.max(Number(filters.limit)||50,1),100);const r=filters.status&&isReturnStatus(filters.status)?await db.query<ReturnRow>('select id,order_id,customer_id,status,reason_code,reason_note,requested_at,updated_at from trust_returns where status=$1 order by updated_at asc limit $2',[filters.status,n]):await db.query<ReturnRow>('select id,order_id,customer_id,status,reason_code,reason_note,requested_at,updated_at from trust_returns order by updated_at asc limit $1',[n]);return r.rows.map(mapReturn);}
export async function listReturnItems(db:Tx,returnId:string){const id=requireId(returnId,'return_id');const r=await db.query<ItemRow>('select id,return_id,order_item_id,quantity,condition,inspection_note from trust_return_items where return_id=$1 order by created_at asc',[id]);return r.rows.map(mapItem);}
export async function approveReturn(db:Tx,input:{returnId:string;actorId:string;note?:string}){return db.transaction(tx=>transitionReturnTx(tx,{returnId:requireId(input.returnId,'return_id'),to:'APPROVED',source:'operations',actorId:requireId(input.actorId,'actor_id'),note:normalizeNote(input.note)}));}
export async function rejectReturn(db:Tx,input:{returnId:string;actorId:string;note?:string}){return db.transaction(tx=>transitionReturnTx(tx,{returnId:requireId(input.returnId,'return_id'),to:'REJECTED',source:'operations',actorId:requireId(input.actorId,'actor_id'),note:normalizeNote(input.note)}));}
export async function markReturnReceived(db:Tx,input:{returnId:string;actorId:string;note?:string}){return db.transaction(tx=>transitionReturnTx(tx,{returnId:requireId(input.returnId,'return_id'),to:'RECEIVED',source:'warehouse',actorId:requireId(input.actorId,'actor_id'),note:normalizeNote(input.note)}));}
export async function startInspection(db:Tx,input:{returnId:string;actorId:string;note?:string}){return db.transaction(tx=>transitionReturnTx(tx,{returnId:requireId(input.returnId,'return_id'),to:'INSPECTING',source:'warehouse',actorId:requireId(input.actorId,'actor_id'),note:normalizeNote(input.note)}));}
export async function inspectReturn(db:Tx,input:InspectionInput){
 const returnId=requireId(input.returnId,'return_id');const actorId=requireId(input.actorId,'actor_id');if(!isInspectionDecision(input.decision))throw new Error('INVALID_INSPECTION_DECISION');if(!isReturnCondition(input.condition))throw new Error('INVALID_INSPECTION_CONDITION');
 if(typeof input.recoverable!=='boolean'||typeof input.restockable!=='boolean')throw new Error('INVALID_INSPECTION_FLAGS');
 return db.transaction(async tx=>{const row=await lockReturn(tx,returnId);if(row.status!=='INSPECTING')throw new Error('RETURN_NOT_IN_INSPECTION');const items=await tx.query<ItemRow>('select id,return_id,order_item_id,quantity,condition,inspection_note from trust_return_items where return_id=$1 for update',[returnId]);if(!items.rows.length)throw new Error('RETURN_ITEMS_REQUIRED');await tx.query('insert into trust_return_inspections(return_id,decision,condition,recoverable,restockable,note,inspector_id) values($1,$2,$3,$4,$5,$6,$7)',[returnId,input.decision,input.condition,input.recoverable,input.restockable,normalizeNote(input.note),actorId]);const next=nextStatusForInspection(input.decision);await tx.query('update trust_return_items set condition=$2,inspection_note=$3 where return_id=$1',[returnId,input.condition,normalizeNote(input.note)]);await tx.query('update trust_returns set status=$2,updated_at=now(),inspected_at=now() where id=$1',[returnId,next]);await appendReturnEvent(tx,{returnId,from:row.status,to:next,source:'inspection',actorId,note:normalizeNote(input.note)});if(next==='APPROVED_REFUND'){await tx.query('insert into trust_return_outcomes(return_id,outcome) values($1,\'REFUND\')',[returnId]);await recoverReturnInventoryTx(tx,{returnId,idempotencyKey:`return:${returnId}:inventory`});}await syncPostSaleCaseTx(tx,{returnId,returnStatus:next,orderId:row.order_id,customerId:row.customer_id,event:'INSPECTION_COMPLETED',metadata:{decision:input.decision}});return{...mapReturn(row),status:next,decision:input.decision,recoverable:input.recoverable,restockable:input.restockable};});}
export async function calculateSettlement(db:Tx,input:{returnId:string;shippingRefundEligible?:boolean;restockingFeeRate?:number}) : Promise<SettlementCalculation>{
 const returnId=requireId(input.returnId,'return_id');const feeRate=input.restockingFeeRate===undefined?0:Math.min(Math.max(Number(input.restockingFeeRate),0),0.5);const shippingEligible=input.shippingRefundEligible===true;return db.transaction(async tx=>{const row=await lockReturn(tx,returnId);if(!['APPROVED_REFUND','REFUND_PENDING'].includes(row.status))throw new Error('RETURN_NOT_REFUND_ELIGIBLE');const r=await tx.query<{subtotal:string}>(`select coalesce(sum(ri.quantity*oi.unit_price),0)::numeric subtotal from trust_return_items ri join trust_order_items oi on oi.id=ri.order_item_id where ri.return_id=$1`,[returnId]);const gross=Number(r.rows[0].subtotal);if(!Number.isFinite(gross)||gross<=0)throw new Error('RETURN_VALUE_UNAVAILABLE');const fee=Math.round(gross*feeRate*100)/100;const shipping=shippingEligible?0:0;const net=Math.round((gross-fee+shipping)*100)/100;if(net<=0)throw new Error('REFUND_AMOUNT_ZERO');return{grossAmount:gross,restockingFee:fee,shippingAdjustment:shipping,netAmount:net,currency:'EGP',eligible:true,reason:'INSPECTION_APPROVED'};});}
export async function requestReturnRefund(db:Tx,input:{returnId:string;actorId:string;idempotencyKey:string;shippingRefundEligible?:boolean;restockingFeeRate?:number}){
 const returnId=requireId(input.returnId,'return_id');const actorId=requireId(input.actorId,'actor_id');const key=requireId(input.idempotencyKey,'idempotency_key');return db.transaction(async tx=>{const hash=requestHash('return.refund',{returnId,shippingRefundEligible:input.shippingRefundEligible===true,restockingFeeRate:input.restockingFeeRate??0});const cached=await ensureIdempotency(tx,key,'return.refund',hash);if(cached)return{...(cached as object),replay:true};const row=await lockReturn(tx,returnId);if(row.status!=='APPROVED_REFUND')throw new Error('RETURN_NOT_REFUND_ELIGIBLE');const calcRow=await tx.query<{subtotal:string}>(`select coalesce(sum(ri.quantity*oi.unit_price),0)::numeric subtotal from trust_return_items ri join trust_order_items oi on oi.id=ri.order_item_id where ri.return_id=$1`,[returnId]);const gross=Number(calcRow.rows[0].subtotal);const fee=Math.round(gross*Math.min(Math.max(Number(input.restockingFeeRate??0),0),0.5)*100)/100;const shipping=input.shippingRefundEligible===true?0:0;const net=Math.round((gross-fee+shipping)*100)/100;if(net<=0)throw new Error('REFUND_AMOUNT_ZERO');const payment=await tx.query<{id:string;status:string;order_id:string}>('select p.id,p.status,p.order_id from trust_payments p join trust_orders o on o.id=p.order_id where o.id=$1 and p.status in (\'captured\',\'partially_refunded\') order by p.created_at desc limit 1 for update',[row.order_id]);if(!payment.rows[0])throw new Error('CAPTURED_PAYMENT_NOT_FOUND');const refund=await tx.query<{id:string}>('insert into trust_refunds(payment_id,amount,reason,status,idempotency_key,return_id) values($1,$2,$3,\'requested\',$4,$5) returning id',[payment.rows[0].id,net,'return:'+returnId,key,returnId]);const settlement=await tx.query<{id:string}>('insert into trust_refund_settlements(refund_id,return_id,gross_amount,restocking_fee,shipping_adjustment,net_amount,status,calculation_json) values($1,$2,$3,$4,$5,$6,\'REQUESTED\',$7::jsonb) returning id',[refund.rows[0].id,returnId,gross,fee,shipping,net,JSON.stringify({gross,fee,shipping,net,actorId})]);await tx.query('update trust_refunds set settlement_id=$2 where id=$1',[refund.rows[0].id,settlement.rows[0].id]);await tx.query('update trust_returns set status=\'REFUND_PENDING\',updated_at=now() where id=$1',[returnId]);await appendReturnEvent(tx,{returnId,from:'APPROVED_REFUND',to:'REFUND_PENDING',source:'operations',actorId,note:'Refund requested'});await syncPostSaleCaseTx(tx,{returnId,returnStatus:'REFUND_PENDING',orderId:row.order_id,customerId:row.customer_id,event:'REFUND_REQUESTED'});await tx.query('insert into trust_outbox_events(event_type,aggregate_id,payload_json) values(\'return.refund.requested\',$1,$2::jsonb)',[returnId,JSON.stringify({returnId,refundId:refund.rows[0].id,settlementId:settlement.rows[0].id,amount:net})]);const result={returnId,refundId:refund.rows[0].id,settlementId:settlement.rows[0].id,amount:net,status:'REFUND_PENDING'};await saveIdempotency(tx,key,'return.refund',result,86400,hash);return{...result,replay:false};});}
export async function applyReturnRefundEvent(db:Tx,input:{refundId:string;status:'succeeded'|'failed';providerReference?:string;eventId:string;provider:string;payload:unknown}){
 return db.transaction(async tx=>{const inserted=await tx.query<{id:string}>(`insert into trust_payment_events(provider,provider_event_id,payment_intent_id,status,payload_json) select $1,$2,p.payment_intent_id,case when $3='succeeded' then 'refunded' else 'failed' end,$4::jsonb from trust_refunds r join trust_payments p on p.id=r.payment_id where r.id=$5 on conflict(provider,provider_event_id) do nothing returning id`,[input.provider,input.eventId,input.status,JSON.stringify(input.payload),input.refundId]);if(!inserted.rows[0])return{ok:true,duplicate:true};const r=await tx.query<{id:string;payment_id:string;return_id:string|null;status:string}>('select id,payment_id,return_id,status from trust_refunds where id=$1 for update',[input.refundId]);if(!r.rows[0])throw new Error('REFUND_NOT_FOUND');const payment=await tx.query<{order_id:string}>('select order_id from trust_payments where id=$1 for update',[r.rows[0].payment_id]);if(!payment.rows[0])throw new Error('PAYMENT_NOT_FOUND');if(input.status==='failed'){await tx.query('update trust_refunds set status=\'failed\',provider_reference=coalesce($2,provider_reference),updated_at=now() where id=$1',[input.refundId,input.providerReference??null]);if(r.rows[0].return_id){await tx.query('update trust_refund_settlements set status=\'FAILED\',updated_at=now() where refund_id=$1',[input.refundId]);await tx.query('update trust_returns set status=\'REFUND_PENDING\',updated_at=now() where id=$1',[r.rows[0].return_id]);await tx.query('insert into trust_outbox_events(event_type,aggregate_id,payload_json) values(\'return.refund.failed\',$1,$2::jsonb)',[r.rows[0].return_id,JSON.stringify({refundId:input.refundId})]);}return{ok:true,duplicate:false,status:'failed'};}
 await tx.query('update trust_refunds set status=\'succeeded\',provider_reference=coalesce($2,provider_reference),updated_at=now() where id=$1',[input.refundId,input.providerReference??null]);await tx.query('update trust_refund_settlements set status=\'SETTLED\',updated_at=now() where refund_id=$1',[input.refundId]);await recordPostSaleFinancialEventTx(tx,{eventType:'REFUND',amount:Number(refund.rows[0].amount),currency:'EGP',idempotencyKey:`return-refund:${input.refundId}`,returnId:r.rows[0].return_id,paymentId:refund.rows[0].payment_id,refundId:input.refundId,metadata:{provider:input.provider,eventId:input.eventId}});await postRefundAccountingTx(tx,{refundId:input.refundId,orderId:payment.rows[0].order_id,amount:Number(refund.rows[0].amount),currency:'EGP'});if(r.rows[0].return_id){await tx.query('update trust_returns set status=\'REFUNDED\',updated_at=now() where id=$1',[r.rows[0].return_id]);await appendReturnEvent(tx,{returnId:r.rows[0].return_id,from:'REFUND_PENDING',to:'REFUNDED',source:'refund_webhook',note:'Provider confirmed refund'});await syncPostSaleCaseTx(tx,{returnId:r.rows[0].return_id,returnStatus:'REFUNDED',orderId:payment.rows[0].order_id,customerId:(await tx.query<{customer_id:string|null}>('select customer_id from trust_orders where id=$1',[payment.rows[0].order_id])).rows[0]?.customer_id??null,event:'REFUND_SUCCEEDED'});await tx.query('insert into trust_outbox_events(event_type,aggregate_id,payload_json) values(\'return.refund.succeeded\',$1,$2::jsonb)',[r.rows[0].return_id,JSON.stringify({refundId:input.refundId,orderId:payment.rows[0].order_id})]);}return{ok:true,duplicate:false,status:'succeeded'};});}

