export async function returnTimeline(db:Tx,returnId:string){const id=requireId(returnId,'return_id');const r=await db.query(`select id,from_status,to_status,source,actor_id,note,created_at from trust_return_events where return_id=$1 order by created_at asc`,[id]);return r.rows;}

