export async function returnOutcomes(db:Tx,returnId:string){const id=requireId(returnId,'return_id');const r=await db.query(`select id,outcome,amount,currency,reference_id,created_at from trust_return_outcomes where return_id=$1 order by created_at desc`,[id]);return r.rows;}

export async function returnSettlements(db:Tx,returnId:string){const id=requireId(returnId,'return_id');const r=await db.query(`select id,refund_id,gross_amount,restocking_fee,shipping_adjustment,net_amount,currency,status,calculation_json,created_at,updated_at from trust_refund_settlements where return_id=$1 order by created_at desc`,[id]);return r.rows;}

export async function returnItemsDetailed(db:Tx,returnId:string){const id=requireId(returnId,'return_id');const r=await db.query(`select ri.id,ri.order_item_id,ri.seller_order_id,ri.quantity,ri.condition,ri.inspection_note,so.merchant_id,oi.product_id,oi.unit_price,p.title from trust_return_items ri join trust_order_items oi on oi.id=ri.order_item_id join trust_products p on p.id=oi.product_id left join trust_seller_orders so on so.id=ri.seller_order_id where ri.return_id=$1 order by ri.created_at asc`,[id]);return r.rows;}

export function returnPolicyRule1(status:ReturnStatus,reason:ReturnReasonCode,condition:ReturnItemCondition,amount:number){const normalized=Number.isFinite(amount)?Math.max(0,Math.round(amount*100)/100):0;const statusAllowed=status!=='CLOSED' && status!=='REJECTED';const reasonAllowed=reason!=='OTHER' || condition!=='DEFECTIVE';const threshold=normalized <= 1000;return {rule:'V234-R01',eligible:statusAllowed&&reasonAllowed&&threshold,threshold:1000,normalized,status,reason,condition};}

