export async function listSellerReturns(db:Tx, merchantId:string, filters:{status?:ReturnStatus;limit?:number}={}){
 const id=requireId(merchantId,'merchant_id');const n=Math.min(Math.max(Number(filters.limit)||50,1),100);
 const params:any[]=[id];let where=`ri.seller_order_id=so.id and so.merchant_id=$1`;
 if(filters.status&&isReturnStatus(filters.status)){params.push(filters.status);where+=` and r.status=$${params.length}`;}
 params.push(n);
 const r=await db.query(`select r.id,r.order_id,r.customer_id,r.status,r.reason_code,r.reason_note,r.requested_at,r.updated_at,so.id seller_order_id,so.seller_order_number,coalesce(sum(ri.quantity*oi.unit_price),0)::numeric seller_return_value from trust_returns r join trust_return_items ri on ri.return_id=r.id join trust_order_items oi on oi.id=ri.order_item_id join trust_seller_orders so on so.id=ri.seller_order_id where ${where} group by r.id,so.id order by r.updated_at asc limit $${params.length}` ,params);
 return r.rows;
}

export async function getSellerReturnForMerchant(db:Tx,input:{merchantId:string;returnId:string}){
 const merchantId=requireId(input.merchantId,'merchant_id');const returnId=requireId(input.returnId,'return_id');
 return db.query(`select r.id,r.order_id,r.customer_id,r.status,r.reason_code,r.reason_note,r.requested_at,r.updated_at,so.id seller_order_id,so.seller_order_number,so.merchant_id,coalesce(sum(ri.quantity*oi.unit_price),0)::numeric seller_return_value from trust_returns r join trust_return_items ri on ri.return_id=r.id join trust_order_items oi on oi.id=ri.order_item_id join trust_seller_orders so on so.id=ri.seller_order_id where r.id=$1 and so.merchant_id=$2 group by r.id,so.id`,[returnId,merchantId]).then(r=>r.rows[0]??undefined);
}

export async function getReturnDashboard(db:Tx){
 const [counts,values,aging,failures]=await Promise.all([
  db.query<{status:ReturnStatus;count:string}>('select status,count(*) count from trust_returns group by status order by status'),
  db.query<{status:string;amount:string}>('select r.status,coalesce(sum(s.net_amount),0)::numeric amount from trust_returns r left join trust_refund_settlements s on s.return_id=r.id group by r.status order by r.status'),
  db.query<{bucket:string;count:string}>('select case when now()-updated_at<interval \'1 day\' then \'0-1d\' when now()-updated_at<interval \'3 days\' then \'1-3d\' when now()-updated_at<interval \'7 days\' then \'3-7d\' else \'7d+\' end bucket,count(*) count from trust_returns where status not in (\'CLOSED\',\'REFUNDED\',\'REJECTED\') group by 1 order by 1'),
  db.query<{status:string;count:string}>('select status,count(*) count from trust_refunds where return_id is not null group by status order by status'),
 ]);
 return {counts:counts.rows,values:values.rows,aging:aging.rows,refunds:failures.rows,surfaceStatus:'LIVE'};
}
export async function reopenFailedRefund(db:Tx,input:{returnId:string;actorId:string;idempotencyKey:string}){
 const returnId=requireId(input.returnId,'return_id');const actorId=requireId(input.actorId,'actor_id');const key=requireId(input.idempotencyKey,'idempotency_key');return db.transaction(async tx=>{const hash=requestHash('return.refund.retry',{returnId});const cached=await ensureIdempotency(tx,key,'return.refund.retry',hash);if(cached)return{...(cached as object),replay:true};const row=await lockReturn(tx,returnId);if(row.status!=='REFUND_PENDING')throw new Error('RETURN_NOT_PENDING_REFUND');const failed=await tx.query<{id:string;amount:string}>('select id,amount from trust_refunds where return_id=$1 and status=\'failed\' order by created_at desc limit 1 for update',[returnId]);if(!failed.rows[0])throw new Error('FAILED_REFUND_NOT_FOUND');await tx.query('update trust_refunds set status=\'requested\',updated_at=now() where id=$1',[failed.rows[0].id]);await tx.query('update trust_refund_settlements set status=\'REQUESTED\',updated_at=now() where refund_id=$1',[failed.rows[0].id]);await tx.query('insert into trust_outbox_events(event_type,aggregate_id,payload_json) values(\'return.refund.retry_requested\',$1,$2::jsonb)',[returnId,JSON.stringify({returnId,refundId:failed.rows[0].id,amount:Number(failed.rows[0].amount),actorId})]);const result={returnId,refundId:failed.rows[0].id,status:'REFUND_PENDING'};await saveIdempotency(tx,key,'return.refund.retry',result,86400,hash);return{...result,replay:false};});
}
